def _quoted(values):
    return "(" + ",".join("'" + value + "'" for value in values) + ")"


def agent_rows():
    """The frozen generation-17 documents, each checked against its own hash."""
    rows = []
    for line in AGENT_SEED_LINES_V17.strip().splitlines():
        identity, kind, version, status, canonical, sha256 = json.loads(line)
        if hashlib.sha256(canonical.encode()).hexdigest() != sha256 or kind not in AGENT_KINDS:
            raise RuntimeError("frozen generation-17 agent definition is inconsistent")
        rows.append({"id": identity, "kind": kind, "version": version, "status": status,
                     "canonical": canonical, "sha256": sha256})
    return rows


def failure_sql(alias: str) -> str:
    """A workflow that ended for its provider, not its model (the engine's ``backtests.FAILURE_SQL``)."""
    prefixes = " OR ".join(f"starts_with(COALESCE({alias}.terminal_reason, ''), '{prefix}')"
                           for prefix in FAILURE_PREFIXES)
    return (f"({alias}.state IN {_quoted(FAILURE_STATES)} OR ({alias}.state = 'FAILED' AND "
            f"(COALESCE({alias}.terminal_reason, '') IN {_quoted(FAILURE_REASONS)} OR {prefixes})))")


# 0035's answer guard with each run's own templates of the step's kind, and the Claude run's starts without its provider
# failures; 0035's artifact guard, with a workflow's template belonging to the run it names.
GUARDS_SQL = """
CREATE OR REPLACE FUNCTION asl_backtest_answer_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = {path} AS $$
DECLARE s record; w record; templates text[]; claude boolean;
BEGIN
    IF asl_is_superuser() THEN RETURN NEW; END IF;
    IF current_user <> 'asl_agent' THEN RAISE EXCEPTION 'a backtest answer is the agent worker''s'; END IF;
    NEW.recorded_at := clock_timestamp();
    SELECT st.run_id, st.kind INTO s FROM backtest_steps st WHERE st.id = NEW.step_id;
    IF NOT FOUND OR s.run_id <> NEW.run_id THEN RAISE EXCEPTION 'a backtest answer answers a step of its run'; END IF;
    PERFORM 1 FROM backtest_runs WHERE id = NEW.run_id AND state = 'RUNNING';
    IF NOT FOUND THEN RAISE EXCEPTION 'a backtest answer needs its run running'; END IF;
    claude := NEW.run_id = '{claude_run}';
    templates := CASE WHEN claude THEN CASE s.kind {claude_cases} END ELSE CASE s.kind {cases} END END;
    IF NEW.outcome = 'UNANSWERED' THEN
        IF EXISTS (SELECT 1 FROM agent_workflows WHERE template_id = ANY(templates)
                AND params->'backtest'->>'step_id' = NEW.step_id::text
                AND state IN ('QUEUED','RUNNING','WAITING_TOOL','WAITING_REVIEW'))
                OR (SELECT count(*) FROM agent_workflows aw WHERE aw.template_id = ANY(templates)
                    AND aw.params->'backtest'->>'step_id' = NEW.step_id::text
                    AND (aw.started_at IS NOT NULL OR aw.state = 'FAILED')
                    AND NOT (aw.state = 'CANCELED' AND COALESCE(aw.terminal_reason, '') = 'YIELDED_TO_DECISION')
                    AND NOT (claude AND {failure}))
                    < {starts} THEN
            RAISE EXCEPTION 'a backtest step is given up only after its starts, with none open'; END IF;
        RETURN NEW;
    END IF;
    SELECT template_id, purpose, state, parent_id, created_by, params INTO w FROM agent_workflows
        WHERE id = NEW.workflow_id;
    IF NOT FOUND OR w.purpose <> 'BACKTEST' OR w.parent_id IS NOT NULL OR w.created_by <> 'SYSTEM'
            OR NOT COALESCE(w.template_id = ANY(templates), false)
            OR w.params->'backtest'->>'step_id' IS DISTINCT FROM NEW.step_id::text
            OR w.params->'backtest'->>'run' IS DISTINCT FROM NEW.run_id THEN
        RAISE EXCEPTION 'a backtest answer comes from the workflow started for its step'; END IF;
    IF NEW.outcome = 'ABSTAINED' THEN
        IF w.state <> 'ABSTAINED' THEN RAISE EXCEPTION 'an abstention names the workflow that abstained'; END IF;
        RETURN NEW;
    END IF;
    IF w.state <> 'RUNNING' THEN RAISE EXCEPTION 'a backtest answer comes from its running workflow'; END IF;
    IF NOT EXISTS (SELECT 1 FROM agent_artifacts WHERE workflow_id = NEW.workflow_id AND kind = 'BACKTEST_ANSWER'
            AND sha256 = NEW.artifact_sha256 AND document -> 'answer' = NEW.answer) THEN
        RAISE EXCEPTION 'a backtest answer is its workflow''s recorded artifact'; END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION asl_backtest_artifact_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = {path} AS $$
DECLARE w record; d jsonb := NEW.document;
BEGIN
    IF asl_is_superuser() THEN RETURN NEW; END IF;
    IF current_user <> 'asl_agent' THEN RAISE EXCEPTION 'a backtest answer comes only from its agent'; END IF;
    SELECT template_id, purpose, state, parent_id, params INTO w FROM agent_workflows WHERE id = NEW.workflow_id;
    IF NOT FOUND OR w.state <> 'RUNNING' OR w.parent_id IS NOT NULL OR w.purpose <> 'BACKTEST'
            OR w.template_id NOT IN {templates} THEN
        RAISE EXCEPTION 'a backtest answer needs its own running backtest workflow'; END IF;
    -- In parentheses: an IF's condition is read up to its first THEN outside them.
    IF w.params->'backtest'->>'run' IS DISTINCT FROM (CASE WHEN w.template_id IN {claude_templates}
            THEN '{claude_run}' ELSE '{chatgpt_run}' END) THEN
        RAISE EXCEPTION 'a backtest workflow answers its own template''s run'; END IF;
    IF d->>'step_id' IS DISTINCT FROM w.params->'backtest'->>'step_id'
            OR d->>'run' IS DISTINCT FROM w.params->'backtest'->>'run' THEN
        RAISE EXCEPTION 'a backtest answer names the step its workflow was started for'; END IF;
    RETURN NEW;
END $$;
"""


def guards_sql() -> str:
    cases = " ".join(f"WHEN '{kind}' THEN ARRAY{list(earlier)}" for kind, earlier, _claude in KINDS)
    claude_cases = " ".join(f"WHEN '{kind}' THEN ARRAY['{claude}']" for kind, _earlier, claude in KINDS)
    return (GUARDS_SQL.replace("{path}", SEARCH_PATH).replace("{claude_cases}", claude_cases)
            .replace("{cases}", cases).replace("{failure}", failure_sql("aw"))
            .replace("{claude_templates}", _quoted(TEMPLATES))
            .replace("{templates}", _quoted((*TEMPLATES_CHATGPT, *TEMPLATES)))
            .replace("{claude_run}", RUN_CLAUDE).replace("{chatgpt_run}", RUN_CHATGPT)
            .replace("{starts}", str(STARTS_PER_STEP)))


def guards_0035_sql() -> str:
    """0035's two guards exactly as 0035 creates them (its own text and builder)."""
    spec = importlib.util.spec_from_file_location("_asl_0035", Path(__file__).with_name("0035_backtest_allowance.py"))
    earlier = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(earlier)
    return earlier.guards_sql()


def checks_sql(runs: tuple[str, ...], codes: tuple[str, ...]) -> str:
    """The run table's id and code checks (0032 named them by default)."""
    return (f"ALTER TABLE backtest_runs DROP CONSTRAINT backtest_runs_id_check, ADD CONSTRAINT backtest_runs_id_check "
            f"CHECK (id IN {_quoted(runs)}), DROP CONSTRAINT backtest_runs_code_check, ADD CONSTRAINT "
            f"backtest_runs_code_check CHECK (code IN {_quoted(codes)})")


def upgrade() -> None:
    op.execute("SET LOCAL lock_timeout = '10s'")
    bind = op.get_bind()
    op.execute(checks_sql((RUN_CHATGPT, RUN_CLAUDE), CODES))
    op.execute(guards_sql())
    for row in agent_rows():
        bind.exec_driver_sql(
            "INSERT INTO agent_definitions (id, kind, version, status, definition, canonical, sha256) "
            "VALUES (%(id)s, %(kind)s, %(version)s, %(status)s, CAST(%(definition)s AS jsonb), %(canonical)s, "
            "%(sha256)s)", {**row, "definition": row["canonical"]})  # one name per use: each has its own type


def downgrade() -> None:
    op.execute("SET LOCAL lock_timeout = '10s'")
    bind = op.get_bind()
    # A runtime profile that binds generation 17 by hash would bind definitions that no longer exist (as 0035's); the
    # Claude run and its workflows need this guard and these checks.
    generation17 = [row["id"] for row in agent_rows()]
    held = bind.exec_driver_sql(
        f"SELECT (SELECT count(*) FROM agent_workflows WHERE template_id IN {_quoted(TEMPLATES)}) "
        f"+ (SELECT count(*) FROM backtest_runs WHERE id <> '{RUN_CHATGPT}' OR code = 'SPEND_CAP_REACHED') "
        f"+ (SELECT count(*) FROM agent_runtime_profiles WHERE profile -> 'definitions' ?| ARRAY{generation17})"
    ).scalar_one()
    if held:
        raise RuntimeError("generation-17 records exist; downgrade refused; fix forward")
    op.execute("ALTER TABLE agent_definitions DISABLE TRIGGER agent_definitions_immutable")
    for row in agent_rows():
        if bind.exec_driver_sql("DELETE FROM agent_definitions WHERE id = %(id)s AND sha256 = %(sha256)s",
                                row).rowcount != 1:
            raise RuntimeError("generation-17 definition mismatch; downgrade refused")
    op.execute("ALTER TABLE agent_definitions ENABLE TRIGGER agent_definitions_immutable")
    op.execute(guards_0035_sql())
    # 0032's own checks: the one run and its four codes (``(id = ...)`` stored as 0032 wrote it).
    op.execute(f"ALTER TABLE backtest_runs DROP CONSTRAINT backtest_runs_id_check, ADD CONSTRAINT "
               f"backtest_runs_id_check CHECK (id = '{RUN_CHATGPT}'), DROP CONSTRAINT backtest_runs_code_check, "
               f"ADD CONSTRAINT backtest_runs_code_check CHECK (code IN {_quoted(CODES_0032)})")
